          + '" no lo es (o no hay ninguna puesta). Un material de terreno esta fundido en la malla de su '
          + 'chunk junto a miles de celdas mas: no se puede girar una sola.');
        return false;
      }
    }
    var ejes = String(m.ejes || 'y').toLowerCase().split('').sort().join('');   // 'xy' e 'yx' son lo mismo
    if (ejes !== 'y' && ejes !== 'xy') {
      console.warn('game.bloques.define("' + clave + '"): ejes de mirar admite "y" (girar) o "xy" '
        + '(girar + cabecear). El alabeo ("z") no esta: nadie mira a nada rodando de lado.');
