          || !isFinite(pv[0]) || !isFinite(pv[1]) || !isFinite(pv[2])) {
        console.warn('game.bloques.define("' + clave + '"): pivote es "auto", el NUMERO de un pivote '
          + 'dibujado en el editor (1 = el primero) o [x,y,z] en coordenadas del OBJETO: bloques desde su '
          + 'esquina, 1 bloque = 16 voxels del dibujo. Un brazo de 1x2x1 que cuelga del hombro es '
          + '[0.5, 2, 0.5]. Sin pivote se usa el 1º dibujado, y si no hay ninguno, el centro de su caja.');
