    if ((senX !== 1 && senX !== -1) || (senY !== 1 && senY !== -1)) {
      console.warn('game.bloques.define("' + clave + '"): sentido es { x:1|-1, y:1|-1 } e invierte '
        + 'el cabeceo (x) o el giro (y). Una pieza que apunta con su eje largo en vez de con su cara '
        + '(un brazo colgando) suele querer { x:-1 }.');
