      else {
        console.warn('game.bloques.define("' + clave + '"): frente son grados (solo horizontal) o '
          + '{ x, y }. Una pieza que apunta con su eje largo hacia abajo (un brazo colgando) quiere '
          + '{ x: -90 }: asi APUNTA al objetivo en vez de solo inclinarse hacia el.');
