      objetivo: obj,                            // 'jugador' · [x,y,z] · clave de material
      porClave: porClave,                       // true: `objetivo` es una clave, no un punto
      deteccion: det,                           // radio en que arranca la persecucion (0 = siempre)
      distancia: dis,                           // a esto se para; si te acercas mas, retrocede
      velocidad: Math.abs(num(g.velocidad, 3)), // bloques/s
      correa: Math.abs(num(g.correa, 24)),      // no se aleja mas de esto del ancla (0 = sin correa)
      volver: g.volver !== false,               // sin objetivo a la vista, regresa al ancla
      ejes: ejes,                               // 'xz' pega al suelo · 'xyz' vuela
