      if (az < minh) minh = az;  if (az > maxh) maxh = az;   // el Z del dibujo es la ALTURA del mundo
      if (ay < minz) minz = ay;  if (ay > maxz) maxz = ay;   // y su Y es la profundidad
    }
    if (!hay) return null;
    var T = MC_T, fl = Math.floor;
    var cx = fl(minx / T) * T, ch = fl(minh / T) * T, cz = fl(minz / T) * T;
    return {
      cx: cx, ch: ch, cz: cz,
      ext: [fl(maxx / T) - fl(minx / T) + 1, fl(maxh / T) - fl(minh / T) + 1, fl(maxz / T) - fl(minz / T) + 1],
      // El contenido DENTRO de esa caja de celdas, en voxeles finos y desde su esquina. `ext` son
      // celdas ENTERAS (la caja sobre la que se gira) y no sirve para medir la pieza: lo que mide
      // su aabb al estamparla lo marca el ultimo voxel. Una cabeza de 15³ mide 15/16 de bloque, no 1.
      min: [minx - cx, minh - ch, minz - cz],
      max: [maxx - cx, maxh - ch, maxz - cz]
