  var mYaw = new Float32Array(16), mLoc = new Float32Array(16);   // se reusan: nada de basura por frame
  var pivEsq = [0, 0, 0];
  var CERO = [0, 0, 0];               // el `o` de una pieza posada: sin celda, no hay resto que corregir
  var docsCache = {};                  // clave -> doc del dibujo, solo para leer sus pivotes al crear

  // Producto de dos matrices 4x4 en el orden de columnas de WebGL: out = a·b (primero b). `out` no
  // puede ser `a` ni `b`. Existe por el punto 3 de arriba y por nada mas.
  function multiplicar(out, a, b) {
    for (var c = 0; c < 4; c++) {
      var b0 = b[c * 4], b1 = b[c * 4 + 1], b2 = b[c * 4 + 2], b3 = b[c * 4 + 3];
      out[c * 4]     = a[0] * b0 + a[4] * b1 + a[8]  * b2 + a[12] * b3;
      out[c * 4 + 1] = a[1] * b0 + a[5] * b1 + a[9]  * b2 + a[13] * b3;
      out[c * 4 + 2] = a[2] * b0 + a[6] * b1 + a[10] * b2 + a[14] * b3;
      out[c * 4 + 3] = a[3] * b0 + a[7] * b1 + a[11] * b2 + a[15] * b3;
    }
  }

  // El punto sobre el que gira una pieza, en coordenadas de mundo SIN desplazar: su pivote si lo
  // trae y, si no, el centro de su caja. Lo consultan dos sitios — el angulo de la mirada y la
  // matriz — y tienen que dar lo MISMO: si la cabeza mide su angulo desde el centro de la caja y
  // luego gira sobre el cuello, apunta sistematicamente un poco al lado y el fallo solo se ve de
  // cerca. Escribe en `salida` y la devuelve: cero basura por pieza y frame.
  function centroGiro(aa, rot, piv, salida) {
    if (piv) { puntoPivote(aa, rot & 3, piv, salida); return salida; }
    salida[0] = (aa[0] + aa[3]) * 0.5;
    salida[1] = (aa[1] + aa[4]) * 0.5;
    salida[2] = (aa[2] + aa[5]) * 0.5;
    return salida;
  }

  // La matriz de UNA pieza:  m = mYaw · T(o) · Rart(articulacion, sobre SU pivote).
  // Falta el T(g) del desplazamiento del agente, que lo suma quien llame (el bicho vivo) o nadie
  // (el preview del editor, que dibuja el agente quieto en el origen).
  // Esta funcion es la unica que sabe componer una pieza, y a proposito: la anima el zombie del
  // Mundo y la dibuja el panel del editor, y si cada uno se hiciera la suya el preview enseñaria
  // un bicho que no es el que luego anda por ahi. No toca `mc` ni el reloj — solo cuentas.
  function matrizPieza(m, mYawIn, aa, rot, piv, art, o, giroMira, fase, activo, andando) {
    var c = centroGiro(aa, rot, piv, pivEsq);
    var giroL = 0, cabL = 0;
    if (art) {
      // ⚠️ DOS INTERRUPTORES DISTINTOS, y confundirlos se ve enseguida:
      //   · `activo` = TE VE → la POSE (los brazos en alto son `base`; al perderte bajan a `reposo`).
      //   · `andando` = SE MUEVE → el VAIVEN.
      // Con el vaiven colgado de `activo`, al volverse a su sitio dejaba de verte y se iba
      // deslizando de lado con las piernas rectas, como un mueble empujado.
      var ang = art.reposo + (art.base - art.reposo) * activo
              + art.amplitud * andando * Math.sin(fase + art.fase * GRADO);
      if (art.eje === 'y') giroL = ang; else cabL = ang;
    }
    giroL += giroMira || 0;   // la mirada ya viene RELATIVA al giro del cuerpo (la calcula quien llama)
    matrizGiro(mLoc, giroL * GRADO, cabL * GRADO, (rot & 3) * 90 * GRADO, c[0], c[1], c[2]);
    mLoc[12] += o[0]; mLoc[13] += o[1]; mLoc[14] += o[2];   // sumar en la ultima columna es T(o)·M
    multiplicar(m, mYawIn, mLoc);
  }

  // El dibujo de una pieza, para sacarle los pivotes. Se pide UNA vez por clave y al CREAR, nunca
  // por frame. La cache muere con esta ejecucion del snippet: si repones los pivotes con 📍, basta
  // con volver a ejecutarlo.
  function docDe(clave) {
    if (Object.prototype.hasOwnProperty.call(docsCache, clave)) return Promise.resolve(docsCache[clave]);
    if (typeof getRoomData !== 'function') return Promise.resolve(null);
    return getRoomData(clave).then(function (d) { return (docsCache[clave] = d || null); },
                                   function () { return (docsCache[clave] = null); });
  }

  function normalizarArticulacion(art) {
    if (!art) return null;
    var eje = String(art.eje || 'x').toLowerCase();
    return {
      pivote: (art.pivote === undefined) ? null : art.pivote,
      base: num(art.base, 0), reposo: num(art.reposo, 0),
      amplitud: num(art.amplitud, 0), fase: num(art.fase, 0),
      eje: (eje === 'y') ? 'y' : 'x'
    };
  }
  // Ojo al nombre: normalizarMirar (sin 'da') es la de 'mirar' por material y son cosas distintas —
  // esta es mucho mas corta porque un rig ya sabe donde tiene el pivote y hacia donde mira el cuerpo.
  function normalizarMirada(m) {
    if (!m) return null;
    var lim = (m.limites && m.limites.y) || [-70, 70];
    return { alcance: Math.abs(num(m.alcance, 12)),
             limY: [num(lim[0], -70), num(lim[1], 70)],
             suavidad: Math.abs(num(m.suavidad, 0.12)) };
  }

  // ── El almacen: data/agentes/*.json ──────────────────────────────────────────────────────────
  // Ojo a la pareja de nombres, que no son sinonimos: `game.agentes` son los DOCUMENTOS guardados
  // en disco (que bichos sabemos hacer) y `game.esqueletos` es lo VIVO en este mundo (que bichos
  // hay ahora mismo y donde). Guardar un agente no planta nada; plantar uno no guarda nada.
  //
  // El documento se guarda TAL CUAL, con las claves que traiga: el servidor solo le impone `id` y
  // `savedAt`. Asi, ampliar el formato mas adelante no rompe los agentes ya guardados ni los
  // vacia al volver a guardarlos desde una version vieja del panel.
  function agentesLista() {
    return fetch('/api/agentes', { cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : []; })
      .catch(function () { console.warn('game.agentes.lista: no he podido hablar con el servidor.'); return []; });
  }

  function agenteCargar(id) {
    id = String(id || '').trim();
    if (!id) { console.warn('game.agentes.cargar: dime el id del agente (game.agentes.lista()).'); return Promise.resolve(null); }
    return fetch('/api/agentes/' + encodeURIComponent(id), { cache: 'no-store' })
      .then(function (r) {
        if (r.ok) return r.json();
        console.warn('game.agentes.cargar: no hay ningun agente "' + id + '". game.agentes.lista() dice cuales hay.');
        return null;
      })
      .catch(function () { console.warn('game.agentes.cargar: no he podido hablar con el servidor.'); return null; });
  }

  function agenteGuardar(doc) {
    if (!doc || typeof doc !== 'object' || !doc.raiz || !doc.raiz.pieza || !Array.isArray(doc.piezas)) {
      console.warn('game.agentes.guardar: dame un documento { nombre, raiz:{pieza}, piezas:[...] }.');
      return Promise.resolve(null);
    }
    return fetch('/api/agentes', { method: 'POST', headers: { 'Content-Type': 'application/json' },
                                   body: JSON.stringify(doc) })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (res) {
        if (!res) { console.warn('game.agentes.guardar: el servidor lo ha rechazado.'); return null; }
        console.log('game.agentes: guardado "' + res.id + '".');
        return res;
      })
      .catch(function () { console.warn('game.agentes.guardar: no he podido hablar con el servidor.'); return null; });
  }

  // ── Crear ────────────────────────────────────────────────────────────────────────────────────
  // (x,y,z) es la celda donde se PLANTA: el agente queda de pie con los pies en su suelo. Devuelve
  // una promesa porque estampar y leer los dibujos van por red.
  //
  // `def` puede ser el documento entero o, mas comodo, el ID de uno guardado: crear('zombie', ...).
  // Lo segundo es lo que evita que el mismo bicho acabe descrito en dos sitios a la vez.
  function crearEsqueleto(def, x, y, z) {
    if (typeof def === 'string') {
      return agenteCargar(def).then(function (doc) { return doc ? crearEsqueleto(doc, x, y, z) : null; });
    }
    if (!def || typeof def !== 'object' || !def.raiz || !def.raiz.pieza || !Array.isArray(def.piezas)) {
      console.warn('game.esqueletos.crear: dame un documento { raiz:{pieza}, piezas:[...], seguir:{...} } '
        + 'o el id de uno guardado (game.agentes.lista()).');
      return Promise.resolve(null);
    }
    if (typeof mc === 'undefined' || !mc.grid || typeof mcStampStruct !== 'function') {
      console.warn('game.esqueletos.crear: el Mundo no está abierto (esto solo va en la pestaña del Mundo).');
      return Promise.resolve(null);
    }
    x = Math.round(num(x, 0)); y = Math.round(num(y, 0)); z = Math.round(num(z, 0));

    // La raiz es la pieza 0 y su `en` es [0,0,0] por definicion: todo lo demas se mide desde ella.
    var brutas = [{ nombre: def.raiz.nombre || 'raíz', pieza: def.raiz.pieza, rot: def.raiz.rot, en: [0, 0, 0] }];
    for (var i = 0; i < def.piezas.length; i++) {
      var q = def.piezas[i];
      if (!q || !q.pieza) { console.warn('game.esqueletos.crear: la pieza nº' + (i + 1) + ' no dice qué material es.'); return Promise.resolve(null); }
      brutas.push(q);
    }
    // Los PIES: la pieza que baja mas. Asi (x,y,z) significa «plantado aqui» y no «con el torso aqui».
    var pies = 0;
    for (i = 0; i < brutas.length; i++) {
      var e = brutas[i].en || [0, 0, 0];
      if (num(e[1], 0) < pies) pies = num(e[1], 0);
    }
    var baseY = y - pies;                       // altura (fraccionaria) de la esquina de la raiz

    var rig = {
      id: ++esqSeq, nombre: def.nombre || ('agente ' + esqSeq), def: def,
      partes: [], quitado: false,
      giro: 0, fase: 0, activo: 0, andando: 0,
      cadencia: Math.abs(num(def.andar && def.andar.cadencia, 0.7)),
      suavidad: Math.abs(num(def.andar && def.andar.suavidad, 0.12)),
      horneado: 0, eje: [0, 0, 0], cuerpo: null, G: null, plantado: [x, y, z]
    };

    // Una promesa por pieza, en cadena: mcStampStruct puede disparar un mcRestampAll (si el atlas
    // crece) y hacerlas en paralelo dejaria a medias las anteriores.
    var cadena = Promise.resolve(), o0 = null;
    brutas.forEach(function (q, idx) {
      cadena = cadena.then(function () {
        var en = q.en || [0, 0, 0];
        var P = [x + num(en[0], 0), baseY + num(en[1], 0), z + num(en[2], 0)];
        var cel = [Math.round(P[0]), Math.round(P[1]), Math.round(P[2])];
        var res = [P[0] - cel[0], P[1] - cel[1], P[2] - cel[2]];
        if (idx === 0) o0 = res;                // el resto de la RAIZ viaja en _sig, no en la matriz:
        // asi golpe()/envAt (que solo saben de _sig) la ven solida EXACTAMENTE donde se la dibuja.
        var parte = {
          nombre: q.nombre || ('pieza ' + idx), clave: q.pieza, rot: (q.rot | 0) & 15,
          cel: cel, o: [res[0] - o0[0], res[1] - o0[1], res[2] - o0[2]],
          piv: null, art: normalizarArticulacion(q.articula), mirar: normalizarMirada(q.mirar),
          giroMira: 0, s: null, idx: -1
        };
        rig.partes.push(parte);
        return docDe(parte.clave).then(function (doc) {
          // El pivote, a coordenadas del OBJETO. Se resuelve UNA vez, aqui, y no por frame.
          var pv = parte.art && parte.art.pivote;
          if (pv !== null && pv !== undefined) {
            if (Array.isArray(pv)) parte.piv = [num(pv[0], 0), num(pv[1], 0), num(pv[2], 0)];
            else {
              parte.piv = doc ? pivoteDeDibujo(doc, Math.round(num(pv, 1))) : null;
              if (!parte.piv) console.warn('game.esqueletos.crear: "' + parte.nombre + '" pide el pivote nº'
                + pv + ' y ese dibujo no lo trae. Ponlo con la herramienta 📍 del editor; mientras tanto '
                + 'girará sobre el centro de su caja.');
            }
          }
          return mcStampStruct(parte.clave, cel[0], cel[1], cel[2], parte.rot, true);
        }).then(function () {
          // mcStampStruct no devuelve la instancia, y ademas puede haberla sustituido por el camino
          // (mcRestampAll). Se coge la ULTIMA que case, que es la recien puesta.
          var ests = mc.structures;
          for (var j = ests.length - 1; j >= 0; j--) {
            var s = ests[j];
            if (s.key === parte.clave && s.ox === cel[0] && s.oy === cel[1] && s.oz === cel[2]
                && (s.rot | 0) === parte.rot && !s._rig) { parte.s = s; parte.idx = j; break; }
          }
          if (!parte.s) { console.warn('game.esqueletos.crear: no encuentro la pieza recién puesta "' + parte.clave + '".'); return; }
          parte.s.efimera = true;               // NO entra en mundo.json (mcSerialize la salta)
          parte.s._rig = rig;
          if (idx === 0) parte.s._rigRaiz = true;
        });
      });
    });

    return cadena.then(function () {
      var R = rig.partes[0];
      if (!R || !R.s || !R.s.aabb) { quitarEsqueleto(rig); return null; }
      rig.horneado = (R.s.rot & 3) * 90;
      var ra = R.s.aabb;
      rig.eje = [(ra[0] + ra[3]) * 0.5, (ra[1] + ra[4]) * 0.5, (ra[2] + ra[5]) * 0.5];
      // La caja con la que CHOCA. Por defecto la union de las piezas, pero un zombie con los brazos
      // en cruz mide 1,4 de ancho y entonces no cabe por una puerta: por eso el documento puede
      // pedir una caja esbelta, como la del jugador, que es lo que hace falta para andar por ahi.
      var b = [Infinity, Infinity, Infinity, -Infinity, -Infinity, -Infinity];
      for (var i = 0; i < rig.partes.length; i++) {
        var P = rig.partes[i], aa = P.s && P.s.aabb; if (!aa) continue;
        for (var k = 0; k < 3; k++) {
          if (aa[k] + P.o[k] < b[k]) b[k] = aa[k] + P.o[k];
          if (aa[k + 3] + P.o[k] > b[k + 3]) b[k + 3] = aa[k + 3] + P.o[k];
        }
      }
      var C = def.cuerpo;
      if (C) {
        var hw = Math.abs(num(C.ancho, 0.6)) * 0.5, hd = Math.abs(num(C.fondo, num(C.ancho, 0.6))) * 0.5;
        var alto = Math.abs(num(C.alto, b[4] - b[1]));
        b = [rig.eje[0] - hw, b[1], rig.eje[2] - hd, rig.eje[0] + hw, b[1] + alto, rig.eje[2] + hd];
      }
      rig.cuerpo = b;
      if (def.seguir === false || def.seguir === null) {
        console.warn('game.esqueletos.crear: un agente sin `seguir` se quedaría plantado para siempre '
          + 'y no haría falta ningún rig. Ponle al menos { deteccion, distancia, velocidad }.');
        quitarEsqueleto(rig); return null;
      }
      rig.G = normalizarSeguir(R.s.key, def.seguir === undefined ? true : def.seguir);
      if (!rig.G) { quitarEsqueleto(rig); return null; }
      if (rig.G.porClave) {
        console.warn('game.esqueletos.crear: un esqueleto todavía no sabe perseguir a otro material; '
          + 'perseguirá al jugador.');
        rig.G = normalizarSeguir(R.s.key, { deteccion: rig.G.deteccion, distancia: rig.G.distancia,
          velocidad: rig.G.velocidad, correa: rig.G.correa, volver: rig.G.volver, ejes: rig.G.ejes,
          suavidad: rig.G.suavidad });
        if (!rig.G) { quitarEsqueleto(rig); return null; }
      }
      // _sig arranca con el resto fraccionario de la raiz: a partir de aqui, «donde esta el agente»
      // es una sola cosa (el _sig) y la solidez sale gratis de los envoltorios de v1.18.
      R.s._sig = { x: o0[0], y: o0[1], z: o0[2], por: 1, pide: 0 };
      esqueletos.push(rig);
      console.log('game.esqueletos: ' + rig.nombre + ' (#' + rig.id + ') plantado en ' + x + ',' + y + ',' + z
        + ' · ' + rig.partes.length + ' piezas efímeras (no entran en el mundo)');
      return rig;
    });
  }

  // ── Quitar ───────────────────────────────────────────────────────────────────────────────────
  function quitarEsqueleto(rig) {
    if (!rig) return 0;
    var n = 0;
    for (var i = 0; i < rig.partes.length; i++) {
      var s = rig.partes[i].s;
      if (!s) continue;
      s._rig = null; s._rigRaiz = false; s._sig = null; s.model = null;
      if (typeof mcRemoveStruct === 'function' && mc.structures.indexOf(s) >= 0) { mcRemoveStruct(s, true); n++; }
      rig.partes[i].s = null;
    }
    rig.quitado = true;
    var j = esqueletos.indexOf(rig); if (j >= 0) esqueletos.splice(j, 1);
    return n;
  }

  // ── Re-adquirir: mc.structures no guarda los MISMOS objetos ──────────────────────────────────
  // mcRestampAll y mcRebakeStructsNear sustituyen cada instancia por una NUEVA en el mismo indice
  // (app.js). Un rig que se fie de sus referencias acaba animando piezas muertas mientras las vivas
  // se quedan plantadas en su celda — es el mismo fallo de «la cabeza no me mira al cargar». Se
  // re-adquiere primero por INDICE (que se conserva en la sustitucion) y, si ya no vale porque
  // alguien borro otra estructura y el array se corrio, por (clave, celda, rot) sin repetir
  // instancia: dos piezas iguales en la misma celda tienen que salir distintas.
  function casaParte(s, P) {
    return !!s && s.key === P.clave && s.ox === P.cel[0] && s.oy === P.cel[1] && s.oz === P.cel[2]
        && (s.rot | 0) === P.rot;
  }
  function readquirir(rig) {
    var ests = mc.structures, ps = rig.partes;
    for (var i = 0; i < ps.length; i++) {
      var P = ps[i], s = ests[P.idx];
      if (s && s === P.s) continue;                     // lo normal: nada ha cambiado, coste cero
      if (!casaParte(s, P)) {
        s = null;
        for (var j = 0; j < ests.length; j++) {
          var e = ests[j];
          if (!casaParte(e, P)) continue;
          var tomada = false;
          for (var k = 0; k < ps.length; k++) if (k !== i && ps[k].s === e) { tomada = true; break; }
          if (!tomada) { s = e; P.idx = j; break; }
        }
      }
      if (!s) { if (P.s) { P.s._rig = null; P.s._rigRaiz = false; } P.s = null; continue; }
      var sigViejo = P.s && P.s._sig;
      if (P.s && P.s !== s) { P.s._rig = null; P.s._rigRaiz = false; }
      P.s = s; s._rig = rig; s.efimera = true;
      if (i === 0) { s._rigRaiz = true; if (sigViejo && !s._sig) s._sig = sigViejo; }
    }
  }

  // ── El paso, por frame ───────────────────────────────────────────────────────────────────────
  function esqueletosPaso(dt) {
    if (!esqueletos.length || typeof mc === 'undefined' || !mc.structures || !mc.pos) return;
    var p = mc.pos;
    for (var r = 0; r < esqueletos.length; r++) {
      var rig = esqueletos[r];
      if (rig.quitado) continue;
      readquirir(rig);
      var R = rig.partes[0], sr = R.s;
      if (!sr || !sr.aabb) continue;                     // sin raiz no hay agente: se queda como este
      var g = sr._sig || (sr._sig = { x: 0, y: 0, z: 0, por: 1, pide: 0 });
      var G = rig.G, hay = true, tx = 0, ty = 0, tz = 0;
      if (G.objetivo === 'jugador') { tx = p[0]; ty = p[1]; tz = p[2]; }
      else { tx = G.objetivo[0]; ty = G.objetivo[1]; tz = G.objetivo[2]; }

      // 1. Andar. La caja que se mueve es la del CUERPO, no la del torso.
      var gx0 = g.x, gz0 = g.z;
      pasoSeguir(sr, rig.cuerpo, g, G, dt, hay, tx, ty, tz);

      // 2. El ciclo de andar avanza con la DISTANCIA RECORRIDA, no con el reloj. Con el reloj, un
      //    zombie frenado contra una pared seguiria pedaleando en el sitio; asi las piernas se paran
      //    solas cuando el cuerpo no avanza, sin una sola condicion especial.
      var avance = Math.sqrt((g.x - gx0) * (g.x - gx0) + (g.z - gz0) * (g.z - gz0));
      rig.fase = (rig.fase + avance * rig.cadencia * 2 * Math.PI) % (2 * Math.PI);
      // `por` = 1 es «fuera de alcance»; 0/2/3 es «te ve» (persiguiendo, con la correa tensa o
      // bloqueada). Ese es el interruptor entre estar parado y estar en faena.
      var k = rig.suavidad > 0 ? 1 - Math.exp(-dt / rig.suavidad) : 1;
      rig.activo += ((g.por === 1 ? 0 : 1) - rig.activo) * k;
      if (rig.activo < 1e-3) rig.activo = 0;
      // Y APARTE: si SE ESTA MOVIENDO. No es lo mismo que «te ve» — al perderte, `volver` lo lleva
      // de vuelta a su ancla, y ahi sigue caminando aunque ya no persiga a nadie.
      rig.andando += ((dt > 0 && avance / dt > 0.15 ? 1 : 0) - rig.andando) * k;
      if (rig.andando < 1e-3) rig.andando = 0;

      // 3. El cuerpo gira hacia el objetivo, medido desde la pose ya horneada (igual que 'mirar').
      //    Y si no persigue pero anda (volviendose a su sitio), mira HACIA DONDE VA: si no, se va
      //    de lado o de espaldas, que es lo que delata que esto es un muñeco y no un bicho.
      //    Parado y sin objetivo se queda como este: nada de desgirarse solo hacia el norte.
      var cxr = rig.eje[0] + g.x, czr = rig.eje[2] + g.z;
      var giroObj = rig.giro;
      if (g.por !== 1 && hay) giroObj = wrap180(Math.atan2(tx - cxr, -(tz - czr)) / GRADO - rig.horneado);
      else if (avance > 1e-4) giroObj = wrap180(Math.atan2(g.x - gx0, -(g.z - gz0)) / GRADO - rig.horneado);
      rig.giro = wrap180(rig.giro + wrap180(giroObj - rig.giro) * k);

      // 4. Una matriz por pieza: M = T(g) · Ryaw · T(o) · Rart.
      matrizGiro(mYaw, rig.giro * GRADO, 0, rig.horneado * GRADO, rig.eje[0], rig.eje[1], rig.eje[2]);
      for (var i = 0; i < rig.partes.length; i++) {
        var P = rig.partes[i], s = P.s, aa = s && s.aabb;
        if (!aa) continue;
        if (P.mirar) {
          // RELATIVO al giro del cuerpo: el cuerpo ya se ha girado hacia ti, y si esto no lo
          // descontase el giro se sumaria dos veces y la cabeza acabaria mirando de lado.
          // Va ANTES de componer, porque el resultado entra en la matriz de esta misma vuelta.
          var L = P.mirar, cp = centroGiro(aa, s.rot, P.piv, pivEsq);
          var ddx = tx - (cp[0] + g.x), ddy = ty - (cp[1] + g.y), ddz = tz - (cp[2] + g.z);
          var obj = 0;
          if (hay && (ddx * ddx + ddy * ddy + ddz * ddz) <= L.alcance * L.alcance) {
            obj = pinza(wrap180(Math.atan2(ddx, -ddz) / GRADO - (s.rot & 3) * 90 - rig.giro), L.limY[0], L.limY[1]);
          }
          var kc = L.suavidad > 0 ? 1 - Math.exp(-dt / L.suavidad) : 1;
          P.giroMira = wrap180(P.giroMira + wrap180(obj - P.giroMira) * kc);
        }
        var m = matrizDe(s);
        matrizPieza(m, mYaw, aa, s.rot, P.piv, P.art, P.o, P.giroMira, rig.fase, rig.activo, rig.andando);
        m[12] += g.x; m[13] += g.y; m[14] += g.z;                     // ...y esto, T(g)·(lo de antes)
      }
    }
  }

  // ── La POSE, para quien quiera DIBUJAR el agente sin tener un Mundo ──────────────────────────
  // El panel del editor tiene que enseñar el bicho moviendose, y la unica forma de que el preview
  // no mienta es que la pose la calcule ESTE codigo — el mismo que anima al que anda por ahi.
  // app.js solo DIBUJA lo que salga de aqui; no compone ni una matriz.
  //
  //   game.esqueletos.preparar(doc|id)  → promesa: resuelve dibujos y pivotes (eso va por red)
  //   game.esqueletos.pose(plantilla, {fase, giro, activo, andando})  → sincrono, para llamar por frame
  //
  // No toca `mc`, no estampa nada y no mira el reloj: son cuentas. Por eso funciona en la pestaña
  // del editor, donde no hay Mundo ninguno.
  //
  // Todo en BLOQUES y con la esquina de la RAIZ en el origen. Aqui NO hay celda donde redondear, asi
  // que cada pieza cae exactamente en su `en` y el `o` de la pieza viva (el resto fraccionario de
  // estampar) es cero. Es la unica diferencia geometrica con el bicho del Mundo, y va a favor: el
  // preview enseña el diseño, no el sitio donde cayo.
  //
  // ⚠️ La `fase` la pone QUIEN LLAMA, en radianes. En el Mundo avanza con la DISTANCIA recorrida
  // (por eso un zombie contra una pared deja de pedalear); un preview no anda a ningun sitio, asi
  // que ahi la mueve el reloj. La cuenta de las articulaciones es la misma en los dos casos.
  function prepararEsqueleto(def) {
    if (typeof def === 'string') {
      return agenteCargar(def).then(function (doc) { return doc ? prepararEsqueleto(doc) : null; });
    }
    if (!def || !def.raiz || !def.raiz.pieza || !Array.isArray(def.piezas)) {
      console.warn('game.esqueletos.preparar: dame un documento { raiz:{pieza}, piezas:[...] } o el id ' +
                   'de uno guardado (game.agentes.lista()).');
      return Promise.resolve(null);
    }
    var brutas = [{ nombre: def.raiz.nombre || 'raíz', pieza: def.raiz.pieza, rot: def.raiz.rot, en: [0, 0, 0] }];
    for (var i = 0; i < def.piezas.length; i++) if (def.piezas[i] && def.piezas[i].pieza) brutas.push(def.piezas[i]);
    var partes = [], cadena = Promise.resolve();
    brutas.forEach(function (q, idx) {
      cadena = cadena.then(function () {
        return docDe(String(q.pieza)).then(function (doc) {
          var c = doc ? cajaDibujo(doc) : null;
          if (!c) {
            console.warn('game.esqueletos.preparar: no encuentro el dibujo de "' + q.pieza + '" (o está vacío).');
            return;
          }
          var rot = ((q.rot | 0) % 4 + 4) % 4;       // el preview no dibuja espejados: solo los 4 cuartos
          var e = q.en || [0, 0, 0], ex = num(e[0], 0), ey = num(e[1], 0), ez = num(e[2], 0);
          var L = ladosDeDibujo(c, rot);
          var art = normalizarArticulacion(q.articula), piv = null, pv = art && art.pivote;
          if (pv !== null && pv !== undefined) {
            if (Array.isArray(pv)) piv = [num(pv[0], 0), num(pv[1], 0), num(pv[2], 0)];
            else {
              piv = pivoteDeDibujo(doc, Math.round(num(pv, 1)));
              if (!piv) console.warn('game.esqueletos.preparar: "' + (q.nombre || q.pieza) + '" pide el pivote nº'
                + pv + ' y ese dibujo no lo trae; girará sobre el centro de su caja.');
            }
          }
          partes.push({
            nombre: q.nombre || ('pieza ' + idx), clave: String(q.pieza), rot: rot,
            aa: [ex, ey, ez, ex + L[0], ey + L[1], ez + L[2]],
            lados: L, piv: piv, art: art,
            dibujo: doc,                       // va dentro para que quien dibuje no lo pida otra vez
            m: new Float32Array(16)            // suya y reusada: pose() la reescribe, no la sustituye
          });
        });
      });
    });
    return cadena.then(function () {
      if (!partes.length) { console.warn('game.esqueletos.preparar: no he podido montar ninguna pieza.'); return null; }
      var ra = partes[0].aa;
      var caja = [Infinity, Infinity, Infinity, -Infinity, -Infinity, -Infinity];
      partes.forEach(function (P) {
        for (var j = 0; j < 3; j++) {
          if (P.aa[j] < caja[j]) caja[j] = P.aa[j];
          if (P.aa[j + 3] > caja[j + 3]) caja[j + 3] = P.aa[j + 3];
        }
      });
      var pl = {
        nombre: def.nombre || 'agente', def: def, partes: partes, caja: caja,
        horneado: partes[0].rot * 90,
        eje: [(ra[0] + ra[3]) * 0.5, (ra[1] + ra[4]) * 0.5, (ra[2] + ra[5]) * 0.5]
      };
      posarEsqueleto(pl, null);            // sale ya posada en reposo: quien la pida puede dibujarla ya
      return pl;
    });
  }

  // Sincrona y sin reservar nada: reescribe la matriz que cada pieza ya tiene. Devuelve las piezas
  // (las MISMAS de la plantilla, no copias) para poder encadenar `.forEach(dibujar)`.
  function posarEsqueleto(pl, opts) {
    if (!pl || !pl.partes || !pl.partes.length) {
      console.warn('game.esqueletos.pose: dame lo que devuelve game.esqueletos.preparar(doc).');
      return [];
    }
    opts = opts || {};
    var fase = num(opts.fase, 0), giro = num(opts.giro, 0),
        activo = pinza(num(opts.activo, 0), 0, 1),
        andando = pinza(num(opts.andando, 0), 0, 1);
    matrizGiro(mYaw, giro * GRADO, 0, pl.horneado * GRADO, pl.eje[0], pl.eje[1], pl.eje[2]);
    for (var i = 0; i < pl.partes.length; i++) {
      var P = pl.partes[i];
      matrizPieza(P.m, mYaw, P.aa, P.rot, P.piv, P.art, CERO, 0, fase, activo, andando);
    }
    return pl.partes;
  }

  function esqueletos_() {
    var filas = esqueletos.map(function (rig) {
      var sr = rig.partes[0] && rig.partes[0].s, g = (sr && sr._sig) || { x: 0, y: 0, z: 0, por: 1, pide: 0 };
      return { id: rig.id, nombre: rig.nombre, piezas: rig.partes.length,
               plantado: rig.plantado.join(','),
               donde: (Math.round((rig.eje[0] + g.x) * 10) / 10) + ',' + (Math.round((rig.eje[2] + g.z) * 10) / 10),
               giro: Math.round(rig.giro) + '°', andando: Math.round(rig.andando * 100) + '%',
               teVe: Math.round(rig.activo * 100) + '%',
               a: Math.round(g.pide * 10) / 10, estado: POR_SIG[g.por] };
    });
    if (!filas.length) console.log('game.esqueletos: no hay ningún agente articulado vivo.');
    else if (console.table) console.table(filas); else console.log(filas);
    return filas;
  }

  // ── Subida suave de escalones: el CUERPO da el salto, el OJO lo alcanza ──────────────────────
  // app.js sube los escalones de golpe (mcMoveAxis: p[1] += h dentro del mismo frame), asi que al
  // andar por una escalera de 8 voxels la camara teletransporta y+0,5 de una vez y se ve a saltos.
  // Es lo mismo que hace Minecraft, y Minecraft lo tapa igual que aqui: la fisica NO se toca (el
  // juego sigue igual de firme, misma colision y mismo alcance de escalon), solo se PINTA al jugador
  // un poco mas abajo y ese retraso se consume en ~0,1 s.
  //
  // Como el ojo se calcula en seis sitios distintos de app.js a partir de mc.pos[1], el desfase se
  // aplica sobre mc.pos[1] al SALIR del frame y se deshace al ENTRAR en el siguiente: entre medias
  // solo hay dibujado, y toda la fisica corre siempre sobre la y de verdad.
  //
  // El estado vive en mc (no en un closure) a proposito: si se reejecuta el snippet, el envoltorio
  // nuevo hereda el desfase que dejo el viejo en vez de dejar al jugador medio bloque hundido.
  function restaurarPaso() {
    var d = mc._pasoDesfase || 0;
    if (!d) return;
    // Si la y no es la que dejamos pintada, es que alguien movio al jugador por su cuenta
    // (game.tp, un respawn, un alPisar…): ese desfase ya no significa nada y se tira.
    // Se repone la y GUARDADA, no pos[1]+d: sumar y restar el desfase no da exactamente el mismo
    // float, y ese pelo de diferencia acabaria en la colision. Asi la fisica es idéntica al bit.
    if (mc._pasoY === mc.pos[1]) mc.pos[1] = mc._pasoReal; else mc._pasoDesfase = 0;
  }

  // El escalon se mide DONDE SE DA: dentro de mcMoveAxis, cuyo unico efecto sobre la y es el
  // `p[1] += h` del auto-escalon (app.js:4919), y cuyos dos unicos llamantes son las dos lineas
  // horizontales de mcUpdate. Deducirlo al final del frame comparando la y NO funciona, y fue el
  // primer intento: en app.js la gravedad va ANTES del horizontal, asi que el frame del escalon
  // termina con vel[1]=0 y `ny === p[1]`, no choca y deja **onGround = false** (app.js:5097). Una
  // guarda que pidiese «estar en el suelo» se apaga justo en el unico frame que hay que suavizar —
  // el dueño no notaba ninguna diferencia entre pasoSuave(0) y pasoSuave(1000). Midiendo aqui no hay
  // heuristica: saltar y trepar no pasan por mcMoveAxis, asi que no se cuelan solos.
  function envolverMoveAxis() {
    if (typeof mcMoveAxis !== 'function') return false;
    var orig = mcMoveAxis._paso ? mcMoveAxis._orig : mcMoveAxis;
    var env = function (ai, target) {
      var y0 = mc.pos[1];
      orig(ai, target);
      var d = mc.pos[1] - y0;
      if (d > 0) mc._pasoSubido = (mc._pasoSubido || 0) + d;
    };
    env._paso = VERSION;
    env._orig = orig;
    window.mcMoveAxis = env;
    return true;
  }

  // ── Solidez de los seguidores: tres envoltorios, cero cambios en app.js ─────────────────────
  //
  // Una pieza movida por matriz se DIBUJA en su sitio nuevo (el culling y la sombra del sol ya
  // transforman por s.model, app.js:5249 y 4758) pero la colision fina no: sondea el bitset con base
  // bx = s.ox*T (app.js:5064). Sin esto la pieza se veria perseguirte y la atravesarias, y ademas
  // dejaria un muro invisible en el ancla. Como TODO el sondeo fino del motor entra por dos globales
  // — mcStructColl y mcFineBoxHit — se arregla envolviendo esas dos, y de paso vale para el jugador,
  // para el rayo de romper y para pegar bloques.
  //
  // Salida rapida: si no hay ninguna desplazada (nDesplazados = 0, el caso normal) los envoltorios
  // devuelven lo del original sin mirar nada. mcCollides se llama varias veces por frame y por eje.
  function envolverColision() {
    if (typeof mcStructColl !== 'function' || typeof mcFineBoxHit !== 'function') return false;
    var origColl = mcStructColl._seguir ? mcStructColl._orig : mcStructColl;
    var origBox = mcFineBoxHit._seguir ? mcFineBoxHit._orig : mcFineBoxHit;
    var origAt = (typeof mcStructAt === 'function') ? (mcStructAt._seguir ? mcStructAt._orig : mcStructAt) : null;

    // 1. El ancla deja de ser solida en cuanto la pieza se va. Si no, quedaria un bloque de aire con
    //    el que chocas donde la pieza ESTABA, que es justo el bug que la gente llama «fantasma».
    // Y con ella se van las EXTREMIDADES de un agente articulado, que no son solidas nunca: el rig
    // las GIRA y estos envoltorios solo saben trasladar, asi que su caja no acompañaria al dibujo —
    // y una caja invisible donde no hay brazo es peor que ningun brazo. El agente choca por su
    // raiz, que si lleva _sig y si es solida donde se la ve.
    var envColl = function (s) {
      if (s._rig && !s._rigRaiz) return null;
      return desplazada(s) ? null : origColl(s);
    };

    // 2. Y aparece donde esta: se resta el desplazamiento a la caja de consulta y se prueba el mismo
    //    bitset. Redondeado a voxel fino (1/16): sondear medio voxel no significa nada, y asi la
    //    pieza es solida en celdas enteras igual que cuando esta quieta.
    var golpe = function (fx0, fy0, fz0, fx1, fy1, fz1) {
      var T = MC_T, ests = mc.structures;
      for (var i = 0; i < ests.length; i++) {
        var s = ests[i];
        if (!desplazada(s)) continue;
        var g = origColl(s); if (!g) continue;
        var q = s._sig, d = g.fdim;
        var bx = s.ox * T + Math.round(q.x * T), by = s.oy * T + Math.round(q.y * T), bz = s.oz * T + Math.round(q.z * T);
        var x0 = Math.max(fx0 - bx, 0), x1 = Math.min(fx1 - bx, d[0] - 1); if (x0 > x1) continue;
        var y0 = Math.max(fy0 - by, 0), y1 = Math.min(fy1 - by, d[1] - 1); if (y0 > y1) continue;
        var z0 = Math.max(fz0 - bz, 0), z1 = Math.min(fz1 - bz, d[2] - 1); if (z0 > z1) continue;
        for (var y = y0; y <= y1; y++) for (var z = z0; z <= z1; z++) {
          var row = (y * d[2] + z) * d[0];
          for (var x = x0; x <= x1; x++) if (g.bits[row + x]) return true;
        }
      }
      return false;
    };
    var envBox = function (fx0, fy0, fz0, fx1, fy1, fz1) {
      if (origBox(fx0, fy0, fz0, fx1, fy1, fz1)) return true;
      if (!nDesplazados) return false;
      return golpe(fx0, fy0, fz0, fx1, fy1, fz1);
    };

    // 3. Y se rompe donde se la ve. mcStructAt es lo que mira el clic de romper (app.js:5912): sin
    //    esto habria que apuntar al ancla vacia para borrar una pieza que esta a diez bloques.
    var envAt = origAt && function (px, py, pz) {
      var s = origAt(px, py, pz);
      if (s || !nDesplazados) return s;
      var T = MC_T, fx = Math.floor(px * T), fy = Math.floor(py * T), fz = Math.floor(pz * T);
      var ests = mc.structures;
      for (var i = 0; i < ests.length; i++) {
        var e = ests[i];
        if (!desplazada(e)) continue;
        var g = origColl(e); if (!g) continue;
        var q = e._sig, d = g.fdim;
        var lx = fx - (e.ox * T + Math.round(q.x * T)), ly = fy - (e.oy * T + Math.round(q.y * T)), lz = fz - (e.oz * T + Math.round(q.z * T));
        if (lx < 0 || ly < 0 || lz < 0 || lx >= d[0] || ly >= d[1] || lz >= d[2]) continue;
        if (g.bits[(ly * d[2] + lz) * d[0] + lx]) return e;
      }
      return null;
    };

    envColl._seguir = VERSION; envColl._orig = origColl; window.mcStructColl = envColl;
    envBox._seguir = VERSION; envBox._orig = origBox; window.mcFineBoxHit = envBox;
    if (envAt) { envAt._seguir = VERSION; envAt._orig = origAt; window.mcStructAt = envAt; }
    return true;
  }

  function suavizarPaso(dt) {
    var d = mc._pasoDesfase || 0;
    var subido = mc._pasoSubido || 0;                   // lo que el auto-escalon levanto este frame
    mc._pasoSubido = 0;
    var tope = PASO * (mc.scale || 1);
    if (TAU_PASO > 0) {
      d += subido;                                      // el ojo se queda donde estaba
      d *= Math.exp(-dt / TAU_PASO);                    // independiente de los fps
      if (d > tope) d = tope;                           // nunca mas de un escalon por detras
      if (d < 1 / 512) d = 0;                           // menos de eso no se ve: se cierra en seco
    } else {
      d = 0;
    }
    mc._pasoDesfase = d;
    if (d) { mc._pasoReal = mc.pos[1]; mc.pos[1] -= d; mc._pasoY = mc.pos[1]; }
  }

  // ── Deslizamiento: seguir patinando al soltar las teclas (el hielo de Minecraft) ─────────────
  // Esto NO se puede hacer dejando puesta mc.vel, y ahi esta el motivo de que el patinaje se conduzca
  // a mano: en el suelo app.js:5094 REESCRIBE vel[0]/vel[2] cada frame desde las teclas, y sin teclas
  // los pone a cero ANTES de mover. Cualquier velocidad que dejemos puesta se borra al frame siguiente
  // sin haber movido nada (por eso 'inercia' es de RAPIDEZ y no de patinaje). Asi que aqui se guarda
  // la marcha llevada (mc._deslizVel), decae con exp(-dt/tau) —igual a 30 que a 120 fps— y se avanza
  // con el MISMO mcMoveAxis que usa app.js, para que muros y auto-escalon se comporten identico.
  // El estado vive en mc y no en una closure para que reejecutar el snippet no te congele a medio derrape.
  // ¿Se esta pilotando? Las mismas cuatro teclas que lee app.js:5086-5089 para fijar la velocidad.
  function hayRumbo() {
    var k = mc.keys || {};
    return !!(k['w'] || k['a'] || k['s'] || k['d']);
  }
  function deslizar(dt) {
    if (!mc.pos || !mc.vel) return;
    var llev = mc._deslizVel;
    if (agarradoPrev) { mc._deslizVel = null; return; }    // colgado de una escalera no se patina
    if (!mc.onGround) {
      // En el aire app.js ya conserva la inercia el solo (air-strafe, app.js:5096): no hay nada que
      // conducir. Solo se sigue la velocidad real para que al aterrizar se retome el derrape.
      if (llev) { llev[0] = mc.vel[0]; llev[1] = mc.vel[2]; }
      return;
    }
    var pie = pieEn();
    var tau = (pie && pie.m && pie.m.cfg && pie.m.cfg.deslizamiento) || 0;
    // Con una tecla de rumbo pulsada MANDA app.js: ya ha fijado vel y ya ha MOVIDO al jugador este
    // frame, asi que empujar aqui ademas seria moverlo DOS VECES. Eso se notaba como un aceleron al
    // salir de una pista rapida con W pulsada (el dueño lo vio y lo achaco al roce): durante los
    // ~3·TAU_ROCE del derrape ibas a marcha normal MAS la marcha guardada. Encima del bloque se
    // memoriza la marcha para cuando sueltes; fuera se olvida, que ahi ya no hay nada que patinar.
    if (hayRumbo()) {
      mc._deslizVel = tau > 0 ? [mc.vel[0], mc.vel[2]] : null;
      return;
    }
    if (!llev) return;             // nunca se CREA marcha fuera del hielo: andar normal no se toca
    // Ya fuera del hielo el derrape no se corta en seco (te sales patinando) pero dura un suspiro:
    // TAU_ROCE. Encima del hielo manda el tau del propio bloque.
    var k = Math.exp(-dt / (tau > 0 ? tau : TAU_ROCE));
    var nx = llev[0] * k, nz = llev[1] * k;
    if (Math.hypot(nx, nz) < DESLIZ_MIN) { mc._deslizVel = null; return; }
    var p = mc.pos;
    if (nx) { var x0 = p[0]; mcMoveAxis(0, x0 + nx * dt); if (p[0] === x0) nx = 0; }   // muro: ese eje muere
    if (nz) { var z0 = p[2]; mcMoveAxis(2, z0 + nz * dt); if (p[2] === z0) nz = 0; }
    if (!nx && !nz) { mc._deslizVel = null; return; }
    mc._deslizVel = [nx, nz];
    mc.vel[0] = nx; mc.vel[2] = nz;   // asi saltar (o pisar un trampolin) se lleva la marcha del derrape
  }

  // ── Instalacion: un unico envoltorio, SIEMPRE el de esta ejecucion ───────────────────────────
  // No apilar envoltorios sigue siendo obligatorio (apilarlos duplicaria la velocidad de trepado en
  // cada pasada), pero NO basta con no reinstalar: el envoltorio viejo se quedaba con SUS closures, y
  // sobre todo con SU tabla de materiales. Reejecutar el snippet creaba una tabla nueva que la fisica
  // no leia jamas, asi que todo lo definido a partir de ahi salia en lista()/info() y no hacia
  // absolutamente nada en el mundo (el dueño lo vio con un trampolin: la consola decia «impulso ↑12»
  // y el bloque no lanzaba). Lo correcto es DESENVOLVER el viejo por su _orig y volver a envolver.
  var previo = (typeof mcUpdate === 'function' && mcUpdate._bloques) ? mcUpdate : null;
  var yaEstaba = !!previo;
  if (typeof mcUpdate !== 'function') {
    console.warn('game.bloques: no encuentro mcUpdate; ¿es esta la pestaña del Mundo?');
  } else {
    var orig = previo ? previo._orig : mcUpdate;
    var envuelto = function (dt) {
      restaurarPaso();                                  // la fisica SIEMPRE arranca en la y de verdad
      var pieAntes = pieEn();
      var agarre = sondearAgarre();                       // ANTES de mover: la gravedad aun no se aplico
      var posAntes = mc.pos ? [mc.pos[0], mc.pos[1], mc.pos[2]] : null;
      // La velocidad horizontal con la que se ENTRA al frame. Hay que leerla aqui porque en el suelo
      // app.js la reescribe entera dentro de orig(dt); despues ya no queda ni rastro de la inercia.
      var velAntes = mc.vel ? [mc.vel[0], mc.vel[2]] : null;
      // 'velocidad' es CONTINUO, no un disparo al entrar como alPisar/impulso: manda mientras el pie
      // este encima. app.js lee mc.speed UNA vez por frame (app.js:5060) y de ahi salen tanto la
      // marcha en el suelo como la aceleracion en el aire, asi que basta con dejarlo puesto durante
      // orig(dt) y devolverlo despues. Se escribe mc.speed a pelo y NO game.playerSpeed: el setter
      // guarda en localStorage, y persistir un valor de bloque le cambiaria la marcha para siempre.
      var velPrevia = mc.speed;
      var fac = (pieAntes && pieAntes.m && pieAntes.m.cfg && pieAntes.m.cfg.velocidad) || 0;
      var objetivo = fac > 0 ? Math.min(VEL_MAX, velPrevia * fac) : velPrevia;
      // INERCIA. Sin esto, la marcha vuelve a la base EL MISMO FRAME en que el pie sale del bloque
      // rapido, y el dueño lo vio en un pasillo de hielo (velocidad:2) que termina en un trampolin:
      // basta UN bloque de suelo normal entre medias para llegar al trampolin a marcha base y salir
      // despedido sin nada de lo que habias corrido (medido: 10 -> 5 con un solo bloque de hueco).
      // Acelerar es instantaneo (pisar hielo se nota ya); FRENAR decae con exp(-dt/TAU), o sea igual
      // a 30 que a 120 fps. Ojo: esto es inercia de RAPIDEZ, no de patinaje: soltar las teclas para
      // en seco, porque en el suelo app.js:5094 pone vel=0 cuando no hay direccion. Lo otro (seguir
      // rodando al soltar) es 'deslizamiento', y va aparte en deslizar().
      // Y es marcha LLEVADA: si el jugador se ha parado de verdad, ya no lleva nada. El decaimiento
      // corria por RELOJ aunque estuvieras quieto, asi que soltar las teclas al salir del bloque te
      // paraba (bien) pero volver a pulsar W dentro de los ~3·TAU siguientes te lanzaba a media
      // marcha del bloque rapido habiendo parado antes — con ×10 son casi 3 s de arranque regalado.
      // Parado = en el suelo, sin tecla de rumbo y sin derrape en curso (si patinas SI llevas algo).
      if (mc.onGround && !hayRumbo() && !mc._deslizVel) mc._velInercia = 0;
      var llevada = mc._velInercia || 0;
      if (llevada > objetivo + 1e-6 && TAU_INERCIA > 0) {
        llevada = objetivo + (llevada - objetivo) * Math.exp(-dt / TAU_INERCIA);
        if (llevada < objetivo + 1 / 64) llevada = objetivo;   // menos de eso no se nota: se cierra
      } else {
        llevada = objetivo;
      }
      mc._velInercia = llevada;
      if (llevada !== velPrevia) mc.speed = llevada;
      try {
        orig(dt);                                         // la fisica de siempre, intacta
      } finally {
        mc.speed = velPrevia;                             // pase lo que pase, no se queda pegada
      }
      if (!mc.grid) return;
      agarradoPrev = !!((agarre && posAntes) ? aplicarTrepado(agarre, posAntes, dt) : null);
      deslizar(dt);                                     // antes de pisar: el derrape puede cambiar de celda
      pisar(pieAntes, velAntes);
      suavizarPaso(dt);                                 // lo ultimo del jugador: de aqui en adelante solo se dibuja
      seguirObjetivos(dt);                              // quien te persigue decide su sitio...
      mirarObjetivos(dt);                               // ...y aqui se compone UNA matriz con giro y sitio
      esqueletosPaso(dt);                               // ...y los agentes articulados, LOS ULTIMOS: el rig
                                                        // manda sobre sus piezas y nadie le pisa la matriz
    };
    envuelto._bloques = VERSION;
    envuelto._orig = orig;
    window.mcUpdate = envuelto;
    // Tercer enganche, y el unico que no es de fisica: la cuarta linea de rayos-X. No es un
    // envoltorio sino un hueco que app.js deja vacio, asi que reasignarlo no apila nada.
    window.mcXrayExtra = etiquetaRayosX;
    envolverMoveAxis();                                   // el segundo enganche: mide el escalon
    envolverColision();                                   // y el cuarto: los seguidores, solidos donde se ven
  }

  var anterior = (typeof game !== 'undefined' && game.bloques) || null;   // antes de pisarlo
  if (previo && anterior && typeof anterior.pasoSuave === 'function') {
    var tauViejo = anterior.pasoSuave();                 // lo que el dueño hubiera ajustado a mano
    if (typeof tauViejo === 'number' && isFinite(tauViejo)) TAU_PASO = tauViejo;
    if (typeof anterior.inercia === 'function') {
      var inerViejo = anterior.inercia();
      if (typeof inerViejo === 'number' && isFinite(inerViejo)) TAU_INERCIA = inerViejo;
    }
    if (typeof anterior.roce === 'function') {
      var roceViejo = anterior.roce();
      if (typeof roceViejo === 'number' && isFinite(roceViejo)) TAU_ROCE = roceViejo;
    }
  }

  game.bloques = {
    version: VERSION,
    define: define, quitar: quitar, lista: lista, info: info,
    avisos: function () { return avisos.slice(); },
    // Cuanto tarda el ojo en alcanzar al cuerpo tras un escalon, en segundos. 0 = como antes
    // (salto instantaneo). Por encima de ~0,15 se nota flotante. Sin argumento, lo consulta.
    pasoSuave: function (tau) {
      if (tau === undefined) return TAU_PASO;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.pasoSuave: dame segundos, 0 para desactivar.'); return TAU_PASO; }
      TAU_PASO = tau;
      if (!tau && mc._pasoDesfase) { restaurarPaso(); mc._pasoDesfase = 0; }   // se apaga sin dejar al ojo hundido
      console.log('game.bloques: subida de escalon ' + (tau ? 'suavizada en ' + tau + ' s' : 'instantánea (como antes)'));
      return TAU_PASO;
    },
    // Segundos que tarda la marcha en volver a la normal al salir de un bloque con 'velocidad'.
    // 0 = como antes (se corta en seco al pisar fuera). Sin argumento, lo consulta.
    inercia: function (tau) {
      if (tau === undefined) return TAU_INERCIA;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.inercia: dame segundos, 0 para desactivar.'); return TAU_INERCIA; }
      TAU_INERCIA = tau;
      if (!tau && typeof mc !== 'undefined') mc._velInercia = 0;
      console.log('game.bloques: la marcha ' + (tau ? 'baja en ' + tau + ' s al salir del bloque rapido' : 'vuelve a la normal en seco (como antes)'));
      return TAU_INERCIA;
    },
    // Segundos que dura el derrape una vez FUERA del bloque deslizante (encima manda el tau del
    // bloque). Corto a proposito: sales patinando, no flotando. 0 = frenazo seco al salir del hielo.
    roce: function (tau) {
      if (tau === undefined) return TAU_ROCE;
      tau = Number(tau);
      if (!isFinite(tau) || tau < 0) { console.warn('game.bloques.roce: dame segundos, 0 para desactivar.'); return TAU_ROCE; }
      TAU_ROCE = tau;
      if (!tau && typeof mc !== 'undefined') mc._deslizVel = null;
      console.log('game.bloques: al salir del bloque deslizante ' + (tau ? 'se sigue patinando ' + tau + ' s' : 'se frena en seco'));
      return TAU_ROCE;
    },
    // Vuelve a mirar contra que esta pegada cada pieza. El contacto se resuelve UNA VEZ por
    // instancia (necesita sondear el mundo alrededor), asi que si rompes el suelo debajo de una
    // pieza con pivote automatico, esto es lo que la pone al dia. Comprobar el mundo por frame
    // para esto no sale a cuenta: son piezas de adorno que casi nunca se despegan.
    repivotar: function () {
      var n = olvidarPivotes(null);
      console.log('game.bloques: ' + n + ' pieza(s) volverán a elegir pivote en el próximo frame.');
      return n;
    },
    mirones: mirones_,
    seguidores: seguidores_,
    // Devolver a su ancla a todos los seguidores (o a los de una clave). Sin argumento vale de boton
    // de panico si una pieza se queda encajada donde no toca: no cambia el cfg, solo la recoge.
    recoger: function (clave) {
      var n = olvidarSeguido(clave || null);
      console.log('game.bloques: ' + n + ' pieza(s) vuelven a su ancla.');
      return n;
    },
    _tabla: tabla,
    _porId: function () { return porId.slice(); }         // para inspeccionar la cache densa
  };

  // ── Agentes articulados ──────────────────────────────────────────────────────────────────────
  // Va aparte de game.bloques a proposito: aquello es por MATERIAL («qué hace el hielo») y esto es
  // por INSTANCIA («este zombie de aquí»). Mezclarlos haria que los dos brazos de un mismo agente
  // tuvieran que comportarse igual, que es justo lo que no puede ser.
  var esqAnterior = (typeof game !== 'undefined' && game.esqueletos) || null;
  // Reejecutar el snippet crea un motor nuevo. Los agentes que ya estaban vivos siguen estampados y
  // siguen llevando su `s._rig`, asi que el motor nuevo tiene que ADOPTARLOS: si no, se quedarian
  // congelados para siempre con su ultima matriz puesta y sin forma de quitarlos.
  if (esqAnterior && esqAnterior._vivos && esqAnterior._vivos.length) {
    var adoptados = esqAnterior._vivos.filter(function (rig) { return rig && !rig.quitado; });
    adoptados.forEach(function (rig) { esqueletos.push(rig); if (rig.id > esqSeq) esqSeq = rig.id; });
    if (adoptados.length) console.log('game.esqueletos: adoptados ' + adoptados.length + ' agente(s) del run anterior.');
  }

  game.esqueletos = {
    version: VERSION,
    crear: crearEsqueleto,
    // Sin argumento se los lleva a TODOS: boton de panico y, sobre todo, lo que hay que llamar antes
    // de reponer un agente para no dejar piezas sueltas por el mapa.
    quitar: function (rig) {
      if (rig === undefined || rig === null) {
        var n = 0, todos = esqueletos.slice();
        todos.forEach(function (r) { n += quitarEsqueleto(r); });
        console.log('game.esqueletos: retiradas ' + n + ' pieza(s) de ' + todos.length + ' agente(s).');
        return n;
      }
      if (typeof rig === 'number') {
        var enc = null;
        esqueletos.forEach(function (r) { if (r.id === rig) enc = r; });
        if (!enc) { console.warn('game.esqueletos.quitar: no hay ningún agente con id ' + rig + '.'); return 0; }
        rig = enc;
      }
      var m = quitarEsqueleto(rig);
      console.log('game.esqueletos: retiradas ' + m + ' pieza(s).');
      return m;
    },
    lista: esqueletos_,
    // Para DIBUJAR un agente fuera del Mundo (el panel del editor). Ver el comentario de preparar().
    preparar: prepararEsqueleto,
    pose: posarEsqueleto,
    _vivos: esqueletos
  };

  // El almacen de documentos, aparte de lo vivo a proposito (ver el comentario de agentesLista).
  game.agentes = {
    version: VERSION,
    lista: agentesLista,
    cargar: agenteCargar,
    guardar: agenteGuardar
  };

  // ── Comportamientos por defecto de este mundo ────────────────────────────────────────────────
  // Los datos estan ARRIBA DEL TODO (DEFECTOS), que es donde se buscan cuando solo se quiere cambiar
  // el mundo; aqui abajo solo se registran, porque es donde define() ya existe y tiene tabla y cache.
  Object.keys(DEFECTOS).forEach(function (k) { define(k, DEFECTOS[k]); });

  // Lo definido A MANO en la consola sobrevive a reejecutar el snippet: los cfg guardados ya estan
  // normalizados y define() los vuelve a normalizar con el codigo de ahora, asi que valen aunque la
  // version anterior tuviera otra forma.
  // Pero SOLO se hereda lo que esta ejecucion NO ha definido: lo que acabas de escribir aqui arriba
  // MANDA. Antes se heredaba todo encima y editar un define no servia absolutamente de nada — el
  // valor nuevo entraba (el define hasta avisaba del ×30) y dos lineas despues la tabla vieja lo
  // volvia a pisar, asi que lista() seguia enseñando el valor viejo y el mundo tampoco cambiaba.
  // Ojo al reves: BORRAR un define de aqui no lo quita, porque se hereda del run anterior. Para eso,
  // game.bloques.quitar('clave') o recargar la pestaña (al recargar no hay nada que heredar).
  var heredado = (previo && anterior && anterior._tabla) || null;
  if (heredado) {
    var claves = Object.keys(heredado).filter(function (k) { return !tabla[k]; });
    claves.forEach(function (k) { define(k, heredado[k]); });
    if (claves.length) console.log('game.bloques: heredados ' + claves.length + ' material(es) definidos a mano (los del snippet mandan).');
  }

  console.log('game.bloques ' + VERSION + ' · ' + Object.keys(tabla).length + ' material(es) con comportamiento'
    + (yaEstaba ? ' (envoltorio REINSTALADO: la física ahora lee esta tabla)' : '')
    + '. game.bloques.lista() / .info()');

})();
